    {
      "path": "integrations/dsh-agentdebugx/bridge/agentdebug_bridge.py",
      "content": "\"\"\"JSON-lines bridge from DeepSeek Harness sessions to AgentDebugX.\n\nThis file belongs to the external DSH plugin. AgentDebugX itself stays\nunmodified and is consumed only through its existing Python APIs.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport json\nimport re\nimport sys\nfrom collections import deque\nfrom datetime import datetime, timezone\nfrom importlib.metadata import PackageNotFoundError, version\nfrom pathlib import Path\nfrom typing import Any, Dict, Iterable, List, Optional, TextIO, get_args\n\nfrom agentdebug.diagnose.pipeline import DiagnosePipeline\nfrom agentdebug.ingest.adapters.importers import convert_directory, convert_file\nfrom agentdebug.runtime.llm import CompletionResult, TokenUsage\nfrom agentdebug.runtime.storage import SQLiteTraceStore\nfrom agentdebug.schema import (\n    AgentEvent,\n    AgentTrajectory,\n    EventType,\n    model_to_dict,\n)\n\n\nJsonObject = Dict[str, Any]\n\n\ndef _safe_text(value: str) -> str:\n    \"\"\"Replace code points that cannot be encoded as UTF-8.\n\n    Harness sessions can carry lone surrogates when a tool result splits a\n    multi-byte character, and both pydantic's JSON serializer and this bridge's\n    stdout reject them. Losing one character beats losing the whole trace.\n    \"\"\"\n\n    try:\n        value.encode('utf-8')\n        return value\n    except UnicodeEncodeError:\n        return value.encode('utf-8', 'replace').decode('utf-8')\n\n\ndef _sanitize(value: Any) -> Any:\n    \"\"\"Return ``value`` with every nested string made UTF-8 encodable.\"\"\"\n\n    if isinstance(value, str):\n        return _safe_text(value)\n    if isinstance(value, dict):\n        return {_safe_text(str(key)): _sanitize(item) for key, item in value.items()}\n    if isinstance(value, list):\n        return [_sanitize(item) for item in value]\n    if isinstance(value, tuple):\n        return [_sanitize(item) for item in value]\n    return value\n\n\ndef _timestamp(milliseconds: Any) -> datetime:\n    try:\n        return datetime.fromtimestamp(float(milliseconds) / 1000.0, tz=timezone.utc)\n    except (TypeError, ValueError, OSError):\n        return datetime.now(timezone.utc)\n\n\ndef _trace_id(session_id: str) -> str:\n    normalized = re.sub(r'[^A-Za-z0-9_.-]+', '_', session_id).strip('_')\n    return f'dsh_{normalized or \"session\"}'\n\n\ndef _event_id(trace_id: str, seq: Any) -> str:\n    try:\n        suffix = str(int(seq))\n    except (TypeError, ValueError):\n        suffix = re.sub(r'[^A-Za-z0-9_-]+', '_', str(seq))\n    return f'{trace_id}_evt_{suffix}'\n\n\ndef _content_text(value: Any) -> str:\n    if isinstance(value, str):\n        return value\n    if isinstance(value, list):\n        parts = [_content_text(item) for item in value]\n        return '\\n'.join(part for part in parts if part)\n    if isinstance(value, dict):\n        if isinstance(value.get('text'), str):\n            return value['text']\n        if 'content' in value:\n            return _content_text(value['content'])\n        if 'message' in value:\n            return _content_text(value['message'])\n    return ''\n\n\ndef _tool_result_details(data: JsonObject) -> tuple[Optional[str], Any, Optional[str]]:\n    message = data.get('message')\n    source = message.get('source', {}) if isinstance(message, dict) else {}\n    call_id = source.get('callId') if isinstance(source, dict) else None\n    blocks = message.get('content', []) if isinstance(message, dict) else []\n    error: Optional[str] = None\n    for block in blocks if isinstance(blocks, list) else []:\n        if not isinstance(block, dict) or block.get('type') != 'tool-result':\n            continue\n        call_id = call_id or block.get('toolCallId')\n        if block.get('isError') is True:\n            error = _content_text(block.get('content')) or 'Tool execution failed.'\n    explicit_error = data.get('error')\n    if isinstance(explicit_error, dict):\n        error = str(explicit_error.get('message') or explicit_error.get('code') or error)\n    return str(call_id) if call_id is not None else None, message, error\n\n\ndef session_to_trajectory(snapshot: JsonObject) -> AgentTrajectory:\n    \"\"\"Convert a public Harness session snapshot into AgentDebugX IR.\"\"\"\n    snapshot = _sanitize(snapshot)\n    session_id = str(snapshot.get('id') or 'session')\n    header = snapshot.get('header') if isinstance(snapshot.get('header'), dict) else {}\n    events = snapshot.get('events') if isinstance(snapshot.get('events'), list) else []\n    trace_id = _trace_id(session_id)\n    started_at = _timestamp(events[0].get('time')) if events else datetime.now(timezone.utc)\n    ended_at: Optional[datetime] = None\n    goal: Optional[str] = None\n    normalized: List[AgentEvent] = []\n    tool_calls: Dict[str, str] = {}\n    skipped_chunks = 0\n\n    for raw in events:\n        if not isinstance(raw, dict):\n            continue\n        event_type = str(raw.get('type') or '')\n        if event_type.startswith('agentdebug/'):\n            continue\n        if event_type == 'assistant/chunk':\n            skipped_chunks += 1\n            continue\n\n        seq = raw.get('seq', len(normalized))\n        data = raw.get('data') if isinstance(raw.get('data'), dict) else {}\n        turn = data.get('turn')\n        step = data.get('step')\n        metadata: JsonObject = {\n            'source': 'deepseek-harness',\n            'dsh_session_id': session_id,\n            'dsh_event_type': event_type,\n            'dsh_seq': seq,\n            'dsh_turn': turn,\n            'dsh_step': step,\n            'native': data,\n        }\n        common: JsonObject = {\n            'event_id': _event_id(trace_id, seq),\n            'trace_id': trace_id,\n            'agent_name': str(snapshot.get('agentId') or 'dsh-agent'),\n            # A Harness turn holds many events under one step number, so\n            # reusing that number leaves attribution unable to name a unique\n            # decision point. Number the mapped events instead, matching the\n            # convention of AgentDebugX's own importers; the Harness turn and\n            # step stay in metadata.\n            'step_index': len(normalized),\n            'timestamp': _timestamp(raw.get('time')),\n            'metadata': metadata,\n        }\n\n        if event_type == 'turn/start':\n            normalized.append(AgentEvent(event_type=EventType.RUN_START, **common))\n        elif event_type == 'turn/end':\n            reason = data.get('reason')\n            error = None\n            if isinstance(reason, dict) and reason.get('kind') == 'error':\n                error = _content_text(reason.get('error')) or json.dumps(\n                    reason.get('error'), ensure_ascii=False\n                )\n            normalized.append(\n                AgentEvent(\n                    event_type=EventType.ERROR if error else EventType.AGENT_STEP,\n                    output=reason,\n                    error=error,\n                    **common,\n                )\n            )\n            ended_at = _timestamp(raw.get('time'))\n        elif event_type in {'step/start', 'step/end'}:\n            normalized.append(\n                AgentEvent(event_type=EventType.AGENT_STEP, output=data, **common)\n            )\n        elif event_type == 'user/message':\n            message_text = _content_text(data)\n            if goal is None and message_text:\n                goal = message_text\n            normalized.append(\n                AgentEvent(\n                    event_type=EventType.OBSERVATION,\n                    input=data,\n                    **common,\n                )\n            )\n        elif event_type in {'request/header', 'request/context'}:\n            normalized.append(\n                AgentEvent(event_type=EventType.LLM_CALL, input=data, **common)\n            )\n        elif event_type == 'assistant/message':\n            normalized.append(\n                AgentEvent(event_type=EventType.LLM_RESPONSE, output=data, **common)\n            )\n        elif event_type == 'tool/call':\n            call_id = str(data.get('callId') or '')\n            arguments: Any = data.get('arguments')\n            if isinstance(arguments, str):\n                try:\n                    arguments = json.loads(arguments)\n                except json.JSONDecodeError:\n                    pass\n            event = AgentEvent(\n                event_type=EventType.TOOL_CALL,\n                module=str(data.get('name') or '') or None,\n                input=arguments,\n                **common,\n            )\n            normalized.append(event)\n            if call_id:\n                tool_calls[call_id] = event.event_id\n        elif event_type == 'tool/result':\n            call_id, output, error = _tool_result_details(data)\n            normalized.append(\n                AgentEvent(\n                    event_type=EventType.ERROR if error else EventType.TOOL_RESULT,\n                    parent_event_id=tool_calls.get(call_id or ''),\n                    output=output,\n                    error=error,\n                    **common,\n                )\n            )\n        elif event_type == 'feedback/record':\n            normalized.append(\n                AgentEvent(event_type=EventType.HUMAN_FEEDBACK, input=data, **common)\n            )\n        else:\n            normalized.append(\n                AgentEvent(event_type=EventType.OBSERVATION, output=data, **common)\n            )\n\n    return AgentTrajectory(\n        trace_id=trace_id,\n        task_id=session_id,\n        goal=goal,\n        framework='deepseek-harness',\n        started_at=started_at,\n        ended_at=ended_at,\n        metadata={\n            'source': 'deepseek-harness',\n            'session_id': session_id,\n            'session_header': header,\n            'skipped_assistant_chunks': skipped_chunks,\n        },\n        events=normalized,\n    )\n\n\ndef _summary(report: Any, dashboard_url: Optional[str]) -> JsonObject:\n    result: JsonObject = {\n        'traceId': report.trace_id,\n        'reportId': report.report_id,\n        'summary': report.summary,\n        'suggestions': list(report.suggestions),\n        'findingCount': len(report.findings),\n    }\n    optional = {\n        'rootCauseEventId': report.root_cause_event_id,\n        'rootCauseAgent': report.root_cause_agent,\n        'rootCauseStepIndex': report.root_cause_step_index,\n        'dashboardUrl': dashboard_url,\n    }\n    result.update({key: value for key, value in optional.items() if value is not None})\n    return result\n\n\ndef _store(path: str) -> SQLiteTraceStore:\n    return SQLiteTraceStore(path)\n\n\ndef _allowed_path(raw_path: Any, raw_roots: Any) -> Path:\n    path = Path(str(raw_path)).expanduser().resolve()\n    roots = raw_roots if isinstance(raw_roots, list) else []\n    for raw_root in roots:\n        root = Path(str(raw_root)).expanduser().resolve()\n        if path == root or root in path.parents:\n            return path\n    raise PermissionError(\n        f'trace path is outside configured traceRoots: {path}'\n    )\n\n\ndef _recorded_outcome(trajectory: AgentTrajectory) -> Optional[JsonObject]:\n    \"\"\"Return the outcome the trace itself recorded, when the source kept one.\n\n    Heuristic detection reasons over events, so a benchmark trace scored as a\n    failure can still yield zero findings. Callers need the recorded outcome to\n    avoid reading \"no findings\" as \"the task succeeded\".\n    \"\"\"\n\n    metadata = trajectory.metadata or {}\n    outcome: JsonObject = {}\n    status = metadata.get('status')\n    if isinstance(status, str):\n        outcome['status'] = status\n    score = metadata.get('result_score')\n    if isinstance(score, (int, float)) and not isinstance(score, bool):\n        outcome['resultScore'] = float(score)\n    infeasible = metadata.get('is_infeasible')\n    if isinstance(infeasible, bool):\n        outcome['isInfeasible'] = infeasible\n    return outcome or None\n\n\ndef _diagnose_deep(trajectory: AgentTrajectory, llm: Any) -> Any:\n    \"\"\"Run the DeepDebug profile, mirroring the CLI's ``--mode deep`` wiring.\n\n    Deterministic findings are computed first and handed to DeepDebug as prior\n    context, so the LLM tier refines the rule layer instead of replacing it.\n    \"\"\"\n\n    from agentdebug.deep import DeepDebugAnalyzer\n    from agentdebug.diagnose.context import DiagnoseContext\n    from agentdebug.diagnose.detect.analyzers import HeuristicAnalyzer\n    from agentdebug.diagnose.recover import suggest_from_context\n    from agentdebug.recovery import DeepDebugRecovery\n\n    detect_report = HeuristicAnalyzer().analyze(trajectory)\n    # Memory retrieval stays off (the analyzer's default), which also keeps the\n    # bridge from creating a deep-memory SQLite file beside the trace store.\n    report = DeepDebugAnalyzer(\n        llm=llm,\n        prior_findings=detect_report.findings,\n    ).analyze(trajectory).report\n    report.metadata['upstream_detect'] = {\n        'analyzer': detect_report.metadata.get('analyzer'),\n        'summary': detect_report.summary,\n        'finding_count': len(detect_report.findings),\n    }\n    context = DiagnoseContext.build(trajectory, report, None)\n    proposals = suggest_from_context(DeepDebugRecovery(), context)\n    report.suggestions = [proposal.suggestion_text for proposal in proposals]\n    return report\n\n\ndef _diagnose_trajectory(\n    trajectory: AgentTrajectory,\n    *,\n    store_path: str,\n    dashboard_url: Optional[str],\n    llm: Any = None,\n) -> JsonObject:\n    deep_error: Optional[str] = None\n    deep_ran = False\n    if llm is None:\n        report = DiagnosePipeline.local_default().run(trajectory).report\n    else:\n        try:\n            report = _diagnose_deep(trajectory, llm)\n            deep_ran = True\n        except Exception as exc:\n            # DeepDebug refuses to answer when it cannot ground a root cause in\n            # a real event, and the host model can be unavailable. Neither is a\n            # reason to throw away the deterministic result the caller would\n            # otherwise have received.\n            host_error = getattr(llm, 'first_error', None)\n            deep_error = (\n                f'host model call failed: {host_error}' if host_error\n                else f'{type(exc).__name__}: {_safe_text(str(exc))}'\n            )\n        if getattr(llm, 'completed', 0) == 0:\n            # DeepDebug's tiers absorb failed calls and can still assemble a\n            # verdict from their fallbacks. A verdict no model ever saw must\n            # not be presented as a model-backed diagnosis.\n            deep_ran = False\n            deep_error = (\n                f'no host model call succeeded: {llm.first_error}'\n                if getattr(llm, 'first_error', None)\n                else 'no host model call succeeded'\n            )\n        elif deep_ran and getattr(llm, 'first_error', None):\n            deep_error = f'some host model calls failed: {llm.first_error}'\n        if not deep_ran:\n            report = DiagnosePipeline.local_default().run(trajectory).report\n    store = _store(store_path)\n    store.save_trajectory(trajectory)\n    store.save_report(report)\n    summary = _summary(report, dashboard_url)\n    summary['mode'] = 'deep' if deep_ran else 'heuristic'\n    if deep_error is not None:\n        summary['deepError'] = deep_error\n    outcome = _recorded_outcome(trajectory)\n    if outcome is not None:\n        summary['recordedOutcome'] = outcome\n    return {\n        'summary': summary,\n        'report': model_to_dict(report),\n    }\n\n\ndef _installed_version() -> str:\n    try:\n        return version('agentdebugx')\n    except PackageNotFoundError:\n        return 'unknown'\n\n\ndef _capabilities() -> JsonObject:\n    \"\"\"Describe the AgentDebugX build that is actually installed.\n\n    Read from the live registries rather than a copied list, so the capability\n    answer cannot drift from the package the bridge imports.\n    \"\"\"\n\n    payload: JsonObject = {'agentdebugxVersion': _installed_version()}\n\n    try:\n        from agentdebug.ingest.adapters.importers import FormatName\n\n        payload['ingestFormats'] = [str(name) for name in get_args(FormatName)]\n    except Exception as exc:  # optional surface: report instead of failing\n        payload['ingestFormatsError'] = str(exc)\n\n    try:\n        from agentdebug.diagnose.registry import list_components\n\n        payload['diagnoseComponents'] = [\n            {\n                'id': component.id,\n                'stage': component.stage,\n                'name': component.name,\n                'enabledByDefault': component.enabled_by_default,\n                'requiresLlm': 'llm_client' in component.dependencies,\n            }\n            for component in list_components()\n        ]\n    except Exception as exc:\n        payload['diagnoseComponentsError'] = str(exc)\n\n    try:\n        from agentdebug.runtime.gui_taxonomy import list_gui_failure_modes\n\n        payload['guiTaxonomyModeCount'] = len(list_gui_failure_modes())\n    except Exception:\n        payload['guiTaxonomyModeCount'] = None\n\n    return payload\n\n\nclass HostLLMClient:\n    \"\"\"``LLMClient`` that borrows the model the Harness host already runs.\n\n    AgentDebugX accepts any object satisfying the ``LLMClient`` protocol, so the\n    LLM tiers can be driven by the host's configured model instead of asking the\n    user to provision a second API key. Completions travel back over the same\n    JSON-lines pipe as a reverse request.\n    \"\"\"\n\n    def __init__(self, protocol: '_Protocol', token: str, model: str) -> None:\n        self._protocol = protocol\n        self._token = token\n        self.model = model\n        #: First transport failure, kept because AgentDebugX's LLM tiers absorb\n        #: individual call errors and would otherwise report a lost model call\n        #: as an inconclusive diagnosis.\n        self.first_error: Optional[str] = None\n        #: Completed calls, so a run that never reached the model cannot be\n        #: presented as a model-backed diagnosis.\n        self.completed = 0\n\n    def complete(\n        self,\n        messages: List[Dict[str, Any]],\n        *,\n        response_format: Optional[Dict[str, Any]] = None,\n        temperature: float = 0.0,\n        max_tokens: int = 2048,\n        timeout: float = 60.0,\n    ) -> CompletionResult:\n        try:\n            result = self._protocol.call(\n                'llm.complete',\n                {\n                    'token': self._token,\n                    'messages': _sanitize(messages),\n                    'responseFormat': response_format,\n                    'temperature': temperature,\n                    'maxTokens': max_tokens,\n                    'timeoutMs': int(timeout * 1000),\n                },\n            )\n        except Exception as exc:\n            if self.first_error is None:\n                self.first_error = _safe_text(str(exc))\n            raise\n        if not isinstance(result, dict):\n            if self.first_error is None:\n                self.first_error = 'host llm returned a malformed completion'\n            raise RuntimeError('host llm returned a malformed completion')\n        self.completed += 1\n        usage = result.get('usage') or {}\n        return CompletionResult(\n            text=str(result.get('text') or ''),\n            raw=result,\n            usage=TokenUsage(\n                prompt_tokens=int(usage.get('promptTokens') or 0),\n                completion_tokens=int(usage.get('completionTokens') or 0),\n                calls=1,\n            ),\n        )\n\n\ndef _host_llm(protocol: Optional['_Protocol'], params: JsonObject) -> Any:\n    \"\"\"Build the host-backed client the requested mode needs, if any.\"\"\"\n\n    mode = str(params.get('mode') or 'heuristic')\n    if mode == 'heuristic':\n        return None\n    if mode != 'deep':\n        raise ValueError(\n            f'unsupported bridge mode {mode!r}; supported modes are heuristic and deep'\n        )\n    if protocol is None:\n        raise ValueError('deep mode requires the bidirectional bridge protocol')\n    llm = params.get('llm')\n    if not isinstance(llm, dict) or not llm.get('token'):\n        raise ValueError('deep mode requires an llm token issued by the host')\n    return HostLLMClient(protocol, str(llm['token']), str(llm.get('model') or 'host'))\n\n\ndef handle(method: str, params: JsonObject, protocol: Optional['_Protocol'] = None) -> Any:\n    if method == 'status':\n        return {'ok': True, 'agentdebugxVersion': _installed_version()}\n\n    if method == 'capabilities':\n        return _capabilities()\n\n    if method == 'ingest_snapshot':\n        trajectory = session_to_trajectory(params['session'])\n        store = _store(str(params['store']))\n        store.save_trajectory(trajectory)\n        return {\n            'traceId': trajectory.trace_id,\n            'eventCount': len(trajectory.events),\n            'lastEventId': trajectory.events[-1].event_id if trajectory.events else None,\n        }\n\n    if method == 'diagnose':\n        llm = _host_llm(protocol, params)\n        trajectory = session_to_trajectory(params['session'])\n        return _diagnose_trajectory(\n            trajectory,\n            store_path=str(params['store']),\n            dashboard_url=params.get('dashboardUrl'),\n            llm=llm,\n        )\n\n    if method == 'diagnose_path':\n        llm = _host_llm(protocol, params)\n        path = _allowed_path(params['path'], params.get('traceRoots'))\n        trace_format = str(params.get('format') or 'auto')\n        trajectory = (\n            convert_directory(path, format=trace_format)\n            if path.is_dir()\n            else convert_file(path, format=trace_format)\n        )\n        return _diagnose_trajectory(\n            trajectory,\n            store_path=str(params['store']),\n            dashboard_url=params.get('dashboardUrl'),\n            llm=llm,\n        )\n\n    if method == 'get_report':\n        report_id = str(params['reportId'])\n        for report in _store(str(params['store'])).list_reports():\n            if report.report_id == report_id:\n                return model_to_dict(report)\n        raise KeyError(f'unknown report id: {report_id}')\n\n    raise ValueError(f'unknown bridge method: {method}')\n\n\ndef _encode_response(response: JsonObject) -> str:\n    \"\"\"Encode one response, degrading to an error rather than raising.\n\n    A single unencodable byte in a result must not take the bridge down for the\n    rest of the session, so encoding failures are reported over the same\n    protocol instead of escaping the serve loop.\n    \"\"\"\n\n    try:\n        return json.dumps(_sanitize(response), ensure_ascii=False) + '\\n'\n    except Exception as exc:\n        fallback = {\n            'id': response.get('id'),\n            'error': {\n                'type': 'ResponseEncodingError',\n                'message': _safe_text(str(exc)),\n            },\n        }\n        return json.dumps(fallback, ensure_ascii=True) + '\\n'\n\n\nclass _MalformedLine(Exception):\n    \"\"\"One unreadable input line, reported without ending the stream.\"\"\"\n\n\nclass _Protocol:\n    \"\"\"Bidirectional JSON-lines channel over the plugin's stdio pipe.\n\n    The host drives the bridge, but LLM-backed diagnosis needs to call back into\n    the host mid-request, so messages travel both ways over the one pipe. A\n    message carrying ``method`` is a request; anything else answers a reverse\n    call this side is waiting on.\n    \"\"\"\n\n    def __init__(self, lines: Iterable[str], out: TextIO) -> None:\n        self._lines = iter(lines)\n        self._out = out\n        self._deferred: 'deque[JsonObject]' = deque()\n        self._sequence = 0\n\n    def write(self, payload: JsonObject) -> None:\n        try:\n            self._out.write(_encode_response(payload))\n            self._out.flush()\n        except Exception:\n            # stdout is the only channel back to the plugin; if even the\n            # degraded payload cannot be written, drop this message and keep\n            # serving rather than killing the process.\n            pass\n\n    def _read(self) -> Optional[JsonObject]:\n        \"\"\"Return the next parsed message, or None once input ends.\"\"\"\n\n        for line in self._lines:\n            if not line.strip():\n                continue\n            try:\n                message = json.loads(line)\n            except Exception as exc:\n                raise _MalformedLine(str(exc)) from exc\n            if not isinstance(message, dict):\n                raise _MalformedLine('expected a JSON object')\n            return message\n        return None\n\n    def next_request(self) -> Optional[JsonObject]:\n        if self._deferred:\n            return self._deferred.popleft()\n        while True:\n            message = self._read()\n            if message is None:\n                return None\n            if message.get('method') is not None:\n                return message\n            # A reply with nobody waiting for it: no in-flight reverse call can\n            # own it, so drop it rather than stalling the loop.\n\n    def call(self, method: str, params: JsonObject, *, depth: int = 0) -> Any:\n        \"\"\"Issue a reverse request and wait for its reply.\n\n        Host requests that arrive while waiting are served inline instead of\n        being queued, so a long LLM-backed run does not stall the automatic\n        per-turn capture behind it.\n        \"\"\"\n\n        self._sequence += 1\n        call_id = f'llm-{self._sequence}'\n        self.write({'id': call_id, 'method': method, 'params': params})\n        while True:\n            try:\n                message = self._read()\n            except _MalformedLine as exc:\n                self.write({\n                    'id': None,\n                    'error': {'type': 'MalformedLine', 'message': _safe_text(str(exc))},\n                })\n                continue\n            if message is None:\n                raise RuntimeError(f'bridge input closed while awaiting {method}')\n            if message.get('method') is not None:\n                if depth >= 8:\n                    self._deferred.append(message)\n                else:\n                    self.write(_respond(self, message, depth=depth + 1))\n                continue\n            if message.get('id') != call_id:\n                continue\n            error = message.get('error')\n            if error:\n                raise RuntimeError(\n                    f\"{error.get('type') or 'HostError'}: {error.get('message') or 'unknown error'}\"\n                )\n            return message.get('result')\n\n\ndef _respond(protocol: _Protocol, request: JsonObject, *, depth: int = 0) -> JsonObject:\n    try:\n        params = request.get('params')\n        if not isinstance(params, dict):\n            params = {}\n        result = handle(str(request.get('method') or ''), params, protocol)\n        return {'id': request.get('id'), 'result': result}\n    except Exception as exc:  # protocol boundary: convert every failure\n        return {\n            'id': request.get('id'),\n            'error': {'type': type(exc).__name__, 'message': _safe_text(str(exc))},\n        }\n\n\ndef serve(\n    lines: Optional[Iterable[str]] = None,\n    out: Optional[TextIO] = None,\n) -> int:\n    # Resolved at call time so a caller can swap either stream.\n    protocol = _Protocol(sys.stdin if lines is None else lines, out or sys.stdout)\n    while True:\n        try:\n            request = protocol.next_request()\n        except _MalformedLine as exc:\n            protocol.write({\n                'id': None,\n                'error': {'type': 'MalformedLine', 'message': _safe_text(str(exc))},\n            })\n            continue\n        if request is None:\n            return 0\n        protocol.write(_respond(protocol, request))\n\n\nif __name__ == '__main__':\n    # The caller always writes UTF-8, but Python defaults stdio to the system\n    # locale encoding, which is a legacy codepage on many Windows installs\n    # (GBK here). Decoding UTF-8 request bytes as GBK corrupts the JSON at the\n    # first non-ASCII character, so pin both directions instead of inheriting.\n    sys.stdin.reconfigure(encoding='utf-8', errors='replace')\n    # Harness content can still surprise us; never let one character abort the\n    # stream that carries every later response.\n    sys.stdout.reconfigure(encoding='utf-8', errors='replace')\n    raise SystemExit(serve())\n"
    },
    {
      "path": "integrations/dsh-agentdebugx/test/plugin.test.js",
      "content": "import assert from 'node:assert/strict'\nimport { spawnSync } from 'node:child_process'\nimport { EventEmitter } from 'node:events'\nimport test from 'node:test'\n\nimport {\n  mkdtempSync,\n  mkdirSync,\n  readFileSync,\n  symlinkSync,\n  utimesSync,\n  writeFileSync,\n} from 'node:fs'\nimport { tmpdir } from 'node:os'\nimport path from 'node:path'\nimport { fileURLToPath } from 'node:url'\nimport { zstdCompressSync } from 'node:zlib'\n\nimport {\n  DashboardProcess,\n  PythonBridge,\n  TraceViewer,\n  apply,\n  completeWithHost,\n  isSessionLogPath,\n  listPersistedSessions,\n  readSessionLog,\n  renderSystemPrompt,\n  resolveRoute,\n  scanZstdFrames,\n  toHostRequest,\n} from '../index.js'\n\nconst python = process.env.AGENTDEBUGX_PYTHON\n  ?? (process.platform === 'win32' ? 'python' : 'python3')\n\ntest('Python bridge reports AgentDebugX availability', async () => {\n  const bridge = new PythonBridge({\n    python,\n    timeoutMs: 10_000,\n  })\n  assert.equal(bridge.process, undefined, 'constructing the plugin must not start Python')\n  try {\n    const status = await bridge.request('status')\n    assert.equal(status.ok, true)\n    assert.equal(typeof status.agentdebugxVersion, 'string')\n  } finally {\n    await bridge.close()\n  }\n})\n\nfunction fakeChild() {\n  const child = new EventEmitter()\n  child.stderr = new EventEmitter()\n  child.killCalls = []\n  child.kill = signal => {\n    child.killCalls.push(signal)\n    queueMicrotask(() => child.emit('exit', 0, signal))\n    return true\n  }\n  return child\n}\n\ntest('dashboard starts once on concurrent first use and closes with the host', async () => {\n  const child = fakeChild()\n  const launches = []\n  let healthy = false\n  const dashboard = new DashboardProcess({\n    python: 'python-test',\n    store: 'trace.sqlite',\n    dashboardUrl: 'http://127.0.0.1:7777',\n    spawnProcess(command, args, options) {\n      launches.push({ command, args, options })\n      queueMicrotask(() => {\n        healthy = true\n      })\n      return child\n    },\n    fetchFn: async () => ({ ok: healthy }),\n    pollIntervalMs: 1,\n  })\n\n  assert.equal(dashboard.process, undefined)\n  assert.deepEqual(await Promise.all([dashboard.ensure(), dashboard.ensure()]), [true, true])\n  assert.equal(launches.length, 1)\n  assert.equal(launches[0].command, 'python-test')\n  assert.deepEqual(launches[0].args, [\n    '-m',\n    'agentdebug.cli',\n    'serve',\n    '--store-sqlite',\n    'trace.sqlite',\n    '--host',\n    '127.0.0.1',\n    '--port',\n    '7777',\n  ])\n\n  await dashboard.close()\n  assert.equal(child.killCalls.length, 1)\n  assert.equal(dashboard.process, undefined)\n})\n\ntest('dashboard reuses an external healthy server without owning it', async () => {\n  let launches = 0\n  const dashboard = new DashboardProcess({\n    python,\n    store: 'trace.sqlite',\n    dashboardUrl: 'http://localhost:7777/',\n    spawnProcess() {\n      launches += 1\n      return fakeChild()\n    },\n    fetchFn: async () => ({ ok: true }),\n  })\n\n  assert.equal(await dashboard.ensure(), false)\n  assert.equal(launches, 0)\n  await dashboard.close()\n  assert.equal(dashboard.process, undefined)\n})\n\n/** A viewer that records URLs instead of launching a browser. */\nclass RecordingViewer extends TraceViewer {\n  constructor(options) {\n    super(options)\n    this.urls = []\n    this.warnings = []\n    this.onWarn = text => this.warnings.push(text)\n  }\n\n  async reachable() {\n    return this.up !== false\n  }\n}\n\ntest('viewer trims a trailing slash from the dashboard url', async () => {\n  const urls = []\n  const viewer = new RecordingViewer({ dashboardUrl: 'http://127.0.0.1:7777/', mode: 'turn' })\n  viewer.launch = url => urls.push(url)\n\n  await viewer.open('session-a', 'dsh_one', 'evt-1')\n  assert.deepEqual(urls, ['http://127.0.0.1:7777/trace/dsh_one/event/evt-1'])\n})\n\ntest('viewer opens once per session in session mode', async () => {\n  const urls = []\n  const viewer = new RecordingViewer({ dashboardUrl: 'http://127.0.0.1:7777', mode: 'session' })\n  viewer.launch = url => urls.push(url)\n\n  assert.equal(await viewer.open('session-a', 'dsh_one', 'evt-1'), true)\n  assert.equal(await viewer.open('session-a', 'dsh_one', 'evt-2'), false)\n  assert.deepEqual(urls, ['http://127.0.0.1:7777/trace/dsh_one/event/evt-1'])\n})\n\ntest('viewer opens each new turn but never the same page twice', async () => {\n  const urls = []\n  const viewer = new RecordingViewer({ dashboardUrl: 'http://127.0.0.1:7777', mode: 'turn' })\n  viewer.launch = url => urls.push(url)\n\n  assert.equal(await viewer.open('session-a', 'dsh_one', 'evt-1'), true)\n  assert.equal(await viewer.open('session-a', 'dsh_one', 'evt-1'), false)\n  assert.equal(await viewer.open('session-a', 'dsh_one', 'evt-2'), true)\n  assert.deepEqual(urls, [\n    'http://127.0.0.1:7777/trace/dsh_one/event/evt-1',\n    'http://127.0.0.1:7777/trace/dsh_one/event/evt-2',\n  ])\n})\n\ntest('viewer encodes ids and omits an absent event', async () => {\n  const urls = []\n  const viewer = new RecordingViewer({ dashboardUrl: 'http://127.0.0.1:7777', mode: 'turn' })\n  viewer.launch = url => urls.push(url)\n\n  await viewer.open('session-a', 'dsh session/one', undefined)\n  assert.deepEqual(urls, ['http://127.0.0.1:7777/trace/dsh%20session%2Fone'])\n})\n\ntest('viewer stays quiet and warns when the dashboard is down', async () => {\n  const urls = []\n  const viewer = new RecordingViewer({ dashboardUrl: 'http://127.0.0.1:7777', mode: 'turn' })\n  viewer.launch = url => urls.push(url)\n  viewer.up = false\n\n  assert.equal(await viewer.open('session-a', 'dsh_one', 'evt-1'), false)\n  assert.deepEqual(urls, [])\n  assert.match(viewer.warnings[0], /not reachable/)\n})\n\ntest('viewer does nothing when auto-open is off', async () => {\n  const urls = []\n  const viewer = new RecordingViewer({ dashboardUrl: 'http://127.0.0.1:7777', mode: 'off' })\n  viewer.launch = url => urls.push(url)\n\n  assert.equal(await viewer.open('session-a', 'dsh_one', 'evt-1'), false)\n  assert.deepEqual(urls, [])\n})\n\nfunction writeSessionLog({ compressed = true, batches = 2 } = {}) {\n  const directory = mkdtempSync(path.join(tmpdir(), 'dsh-session-'))\n  const sessionDir = path.join(directory, 'session-abc')\n  mkdirSync(sessionDir)\n  const header = {\n    type: 'session',\n    version: 0,\n    id: 'session-abc',\n    createdAt: 1787062235243,\n    cwd: 'C:/workspace',\n  }\n  const events = [\n    { type: 'turn/start', seq: 0, time: 1787062235300, data: { turn: 1 } },\n    {\n      type: 'user/message',\n      seq: 1,\n      time: 1787062235301,\n      data: { role: 'user', content: [{ type: 'text', text: 'Fix the build.' }] },\n    },\n    { type: 'turn/end', seq: 2, time: 1787062235302, data: { turn: 1, reason: { kind: 'completed' } } },\n  ]\n  const groups = batches === 1\n    ? [[header, ...events]]\n    : [[header], events]\n  const chunks = groups.map(group => `${group.map(record => JSON.stringify(record)).join('\\n')}\\n`)\n  const file = path.join(sessionDir, compressed ? 'session.jsonl.zstd' : 'session.jsonl')\n  writeFileSync(\n    file,\n    compressed\n      ? Buffer.concat(chunks.map(chunk => zstdCompressSync(Buffer.from(chunk, 'utf8'))))\n      : chunks.join(''),\n  )\n  return { sessionDir, file }\n}\n\nfunction writeListedSession(root, {\n  workspace = 'workspace-a',\n  sessionId = 'session-abc',\n  cwd = `C:/${workspace}`,\n  prompt = 'Fix the build.',\n  compressed = true,\n  modifiedAt = new Date('2026-08-24T12:00:00Z'),\n} = {}) {\n  const sessionDir = path.join(root, workspace, sessionId)\n  mkdirSync(sessionDir, { recursive: true })\n  const records = [\n    { type: 'session', id: sessionId, cwd, workspace },\n    {\n      type: 'user/message',\n      seq: 1,\n      data: { role: 'user', content: [{ type: 'text', text: prompt }] },\n    },\n    { type: 'turn/end', seq: 2, data: { turn: 1, reason: { kind: 'completed' } } },\n  ]\n  const text = `${records.map(record => JSON.stringify(record)).join('\\n')}\\n`\n  const file = path.join(sessionDir, compressed ? 'session.jsonl.zstd' : 'session.jsonl')\n  writeFileSync(\n    file,\n    compressed ? zstdCompressSync(Buffer.from(text, 'utf8')) : text,\n  )\n  utimesSync(file, modifiedAt, modifiedAt)\n  return { sessionDir, file }\n}\n\ntest('reads a Harness session log across concatenated zstd frames', () => {\n  const { file } = writeSessionLog({ batches: 2 })\n  const raw = readFileSync(file)\n\n  assert.equal(scanZstdFrames(raw).length, 2)\n  const session = readSessionLog(file)\n  assert.equal(session.id, 'session-abc')\n  assert.equal(session.header.cwd, 'C:/workspace')\n  assert.deepEqual(session.events.map(event => event.type), [\n    'turn/start',\n    'user/message',\n    'turn/end',\n  ])\n})\n\ntest('reads a session log from its session directory and uncompressed', () => {\n  const { sessionDir } = writeSessionLog({ compressed: false, batches: 1 })\n\n  assert.equal(isSessionLogPath(sessionDir), true)\n  assert.equal(readSessionLog(sessionDir).events.length, 3)\n})\n\ntest('session listing enumerates compressed and plain logs with bounded metadata', () => {\n  const root = mkdtempSync(path.join(tmpdir(), 'dsh-listing-'))\n  const newest = writeListedSession(root, {\n    workspace: 'game-tools',\n    sessionId: 'session-new',\n    cwd: 'C:/work/game-tools',\n    prompt: `  Diagnose\\n${'a'.repeat(500)}  `,\n    modifiedAt: new Date('2026-08-24T13:00:00Z'),\n  })\n  writeListedSession(root, {\n    workspace: 'docs',\n    sessionId: 'session-old',\n    compressed: false,\n    modifiedAt: new Date('2026-08-24T12:00:00Z'),\n  })\n  writeFileSync(path.join(newest.sessionDir, 'session.jsonl'), '{\"not\":\"preferred\"}\\n')\n\n  const result = listPersistedSessions(root)\n\n  assert.equal(result.available, true)\n  assert.equal(result.scanned, 2)\n  assert.equal(result.skipped, 0)\n  assert.equal(result.limit, 10)\n  assert.deepEqual(result.sessions.map(session => session.sessionId), ['session-new', 'session-old'])\n  assert.equal(result.sessions[0].path, path.resolve(newest.file))\n  assert.equal(result.sessions[0].workspace, 'game-tools')\n  assert.equal(result.sessions[0].cwd, 'C:/work/game-tools')\n  assert.equal(result.sessions[0].firstUserPrompt.includes('\\n'), false)\n  assert.ok(result.sessions[0].firstUserPrompt.length <= 240)\n  assert.equal(result.sessions[0].modifiedAt, '2026-08-24T13:00:00.000Z')\n  assert.equal(typeof result.sessions[0].modifiedTimeMs, 'number')\n})\n\ntest('session listing ranks token matches deterministically and clamps limits', () => {\n  const root = mkdtempSync(path.join(tmpdir(), 'dsh-ranking-'))\n  writeListedSession(root, {\n    workspace: 'alpha',\n    sessionId: 'session-older',\n    prompt: 'Repair alpha parser failure',\n    modifiedAt: new Date('2026-08-24T11:00:00Z'),\n  })\n  writeListedSession(root, {\n    workspace: 'beta',\n    sessionId: 'session-newer',\n    prompt: 'Alpha release notes',\n    modifiedAt: new Date('2026-08-24T13:00:00Z'),\n  })\n  writeListedSession(root, {\n    workspace: 'gamma',\n    sessionId: 'session-gamma',\n    prompt: 'Unrelated task',\n    modifiedAt: new Date('2026-08-24T14:00:00Z'),\n  })\n\n  const ranked = listPersistedSessions(root, { query: '  ALPHA   parser ', limit: 3 })\n  assert.deepEqual(ranked.sessions.map(session => session.sessionId), [\n    'session-older',\n    'session-newer',\n  ])\n  assert.equal(ranked.query, 'alpha parser')\n  assert.equal(listPersistedSessions(root, { limit: 0 }).limit, 1)\n  assert.equal(listPersistedSessions(root, { limit: -3 }).limit, 1)\n  assert.equal(listPersistedSessions(root, { limit: 2.9 }).limit, 2)\n  assert.equal(listPersistedSessions(root, { limit: 500 }).limit, 25)\n  assert.equal(listPersistedSessions(root, { limit: Number.POSITIVE_INFINITY }).limit, 10)\n})\n\ntest('session listing contains corrupt logs and does not follow symlinks', () => {\n  const root = mkdtempSync(path.join(tmpdir(), 'dsh-contained-'))\n  writeListedSession(root, { sessionId: 'session-good' })\n  const corruptDir = path.join(root, 'workspace-b', 'session-corrupt')\n  mkdirSync(corruptDir, { recursive: true })\n  writeFileSync(path.join(corruptDir, 'session.jsonl.zstd'), Buffer.from('broken'))\n  const outside = mkdtempSync(path.join(tmpdir(), 'dsh-outside-'))\n  writeListedSession(outside, { sessionId: 'session-outside' })\n  try {\n    symlinkSync(outside, path.join(root, 'linked-outside'), 'junction')\n  } catch {\n    // Windows developer mode may disable symlink creation; corruption coverage\n    // remains valid and the traversal test is skipped on that host.\n  }\n\n  const result = listPersistedSessions(root, { query: 'session' })\n\n  assert.deepEqual(result.sessions.map(session => session.sessionId), ['session-good'])\n  assert.equal(result.scanned, 2)\n  assert.equal(result.skipped, 1)\n  assert.equal(result.warnings.length, 1)\n  assert.ok(result.warnings[0].length <= 300)\n  assert.equal(result.sessions.some(session => session.path.includes(outside)), false)\n  assert.deepEqual(listPersistedSessions(undefined).sessions, [])\n  assert.equal(listPersistedSessions(undefined).available, false)\n  assert.deepEqual(listPersistedSessions(path.join(root, 'missing')).sessions, [])\n})\n\ntest('list tool registration is Node-only and prompt contract requires disambiguation', async () => {\n  const root = mkdtempSync(path.join(tmpdir(), 'dsh-list-tool-'))\n  writeListedSession(root, { sessionId: 'session-choice', prompt: 'Repair the renderer' })\n  const tools = new Map()\n  const promptSections = []\n  const ctx = {\n    logger: { warn() {} },\n    llm: {},\n    effect() {},\n    on() {},\n    commands: { register() {} },\n    systemPrompt: { section(section) { promptSections.push(section) } },\n    tools: { register(tool) { tools.set(tool.name, tool) } },\n  }\n\n  apply(ctx, {\n    python: 'python-must-not-start',\n    store: '.agentdebug/test.sqlite',\n    dashboardUrl: 'http://127.0.0.1:7777',\n    timeoutMs: 10,\n    deepTimeoutMs: 10,\n    autoCapture: false,\n    autoOpen: 'off',\n    traceRoots: [],\n    dshSessionsRoot: root,\n  })\n\n  const tool = tools.get('agentdebug_list_sessions')\n  assert.ok(tool)\n  assert.equal(tools.has('agentdebug_diagnose'), true)\n  const result = await tool.execute({ query: 'renderer', limit: 4 }, {})\n  assert.equal(result.sessions[0].sessionId, 'session-choice')\n  assert.equal(result.limit, 4)\n  assert.match(tool.description, /past|external/i)\n  assert.match(tool.description, /choose|confirm/i)\n  assert.match(tools.get('agentdebug_diagnose').description, /current|latest|just-now/i)\n  assert.match(tools.get('agentdebug_analyze_trace').description, /list|confirm/i)\n  const template = readFileSync(new URL('../SYSTEM_PROMPT.md', import.meta.url), 'utf8')\n  const expectedPrompt = renderSystemPrompt(template, {\n    capturePolicy: 'AgentDebugX stays stopped until an AgentDebugX tool or /agentdebug command is explicitly used.',\n    openPolicy: 'Automatic viewer opening is disabled.',\n    sessionsRootHint: root,\n  })\n  assert.equal(promptSections[0].text, expectedPrompt)\n  assert.doesNotMatch(promptSections[0].text, /\\{\\{[^{}]*\\}\\}/)\n  assert.match(promptSections[0].text, /agentdebug_list_sessions/)\n  assert.match(promptSections[0].text, /past or external/i)\n  assert.match(promptSections[0].text, /present the matching candidates/i)\n  assert.match(promptSections[0].text, /ask the user to choose/i)\n  assert.match(promptSections[0].text, /never silently substitute the current session/i)\n  assert.match(promptSections[0].text, /current, latest, or just-now/i)\n  assert.match(promptSections[0].text, /saved path is explicit or confirmed/i)\n  assert.match(promptSections[0].text, /heuristic.*deterministic/i)\n  assert.match(promptSections[0].text, /deep runs the DeepDebug profile/i)\n  assert.match(promptSections[0].text, /recordedOutcome/)\n  assert.match(promptSections[0].text, /CLI against the same store/i)\n  assert.match(promptSections[0].text, /agentdebug_capabilities/)\n})\n\ntest('system prompt renderer replaces every required placeholder', () => {\n  const template = [\n    '{{CAPTURE_POLICY}}',\n    '{{OPEN_POLICY}}',\n    '{{SESSIONS_ROOT_HINT}}',\n    '{{CAPTURE_POLICY}}',\n  ].join('\\n')\n\n  assert.equal(\n    renderSystemPrompt(template, {\n      capturePolicy: 'capture-policy',\n      openPolicy: 'open-policy',\n      sessionsRootHint: 'sessions-root',\n    }),\n    ['capture-policy', 'open-policy', 'sessions-root', 'capture-policy'].join('\\n'),\n  )\n})\n\ntest('system prompt renderer rejects missing and unresolved placeholders', () => {\n  const values = {\n    capturePolicy: 'capture-policy',\n    openPolicy: 'open-policy',\n    sessionsRootHint: 'sessions-root',\n  }\n  const valid = '{{CAPTURE_POLICY}} {{OPEN_POLICY}} {{SESSIONS_ROOT_HINT}}'\n\n  assert.throws(\n    () => renderSystemPrompt(valid.replace('{{OPEN_POLICY}}', ''), values),\n    /\\{\\{OPEN_POLICY\\}\\}/,\n  )\n  assert.throws(\n    () => renderSystemPrompt(valid, { ...values, capturePolicy: undefined }),\n    /capturePolicy/,\n  )\n  assert.throws(\n    () => renderSystemPrompt(`${valid} {{UNKNOWN_POLICY}}`, values),\n    /unresolved.*\\{\\{UNKNOWN_POLICY\\}\\}/i,\n  )\n})\n\ntest('package dry-run includes the system prompt Markdown asset', () => {\n  const command = process.platform === 'win32' ? process.env.ComSpec ?? 'cmd.exe' : 'npm'\n  const args = process.platform === 'win32'\n    ? ['/d', '/s', '/c', 'npm.cmd pack --dry-run --json']\n    : ['pack', '--dry-run', '--json']\n  const result = spawnSync(command, args, {\n    cwd: fileURLToPath(new URL('..', import.meta.url)),\n    encoding: 'utf8',\n  })\n  assert.equal(\n    result.status,\n    0,\n    `npm pack --dry-run failed:\\n${result.stderr || result.stdout}`,\n  )\n  const manifest = JSON.parse(result.stdout)\n  const files = manifest.flatMap(entry => entry.files ?? [])\n    .map(file => file.path.replaceAll('\\\\', '/'))\n  assert.ok(\n    files.includes('SYSTEM_PROMPT.md'),\n    `package manifest omitted SYSTEM_PROMPT.md:\\n${files.join('\\n')}`,\n  )\n})\n\ntest('a plain trajectory file is not mistaken for a session log', () => {\n  const directory = mkdtempSync(path.join(tmpdir(), 'dsh-trace-'))\n  const file = path.join(directory, 'trajectory.json')\n  writeFileSync(file, '{}')\n\n  assert.equal(isSessionLogPath(file), false)\n})\n\ntest('non-ASCII trace content survives the bridge pipe', async () => {\n  // A legacy system codepage used to corrupt the request here, and the reply\n  // came back uncorrelatable, so the call hung until its timeout.\n  const bridge = new PythonBridge({ python, timeoutMs: 20_000 })\n  const text = '构建失败：找不到模块 ✅ 🚀'\n  try {\n    const result = await bridge.request('diagnose', {\n      session: {\n        id: 'session-unicode',\n        header: { cwd: 'C:/workspace' },\n        events: [\n          { type: 'turn/start', seq: 0, time: 1, data: { turn: 1 } },\n          {\n            type: 'user/message',\n            seq: 1,\n            time: 2,\n            data: { role: 'user', content: [{ type: 'text', text }] },\n          },\n          { type: 'turn/end', seq: 2, time: 3, data: { turn: 1, reason: { kind: 'completed' } } },\n        ],\n      },\n      store: path.join(mkdtempSync(path.join(tmpdir(), 'dsh-store-')), 'agentdebug.sqlite'),\n      mode: 'heuristic',\n    })\n    assert.equal(result.summary.traceId, 'dsh_session-unicode')\n  } finally {\n    await bridge.close()\n  }\n})\n\ntest('an uncorrelatable bridge error fails the in-flight request', async () => {\n  const bridge = new PythonBridge({ python, timeoutMs: 20_000, onStderr: () => {} })\n  bridge.start()\n  const inFlight = bridge.request('status', {})\n  bridge.accept(JSON.stringify({ id: null, error: { type: 'JSONDecodeError', message: 'bad' } }))\n\n  await assert.rejects(inFlight, /JSONDecodeError: bad/)\n  await bridge.close()\n})\n\ntest('a persisted Harness session diagnoses through the bridge', async () => {\n  const { file } = writeSessionLog()\n  const store = path.join(mkdtempSync(path.join(tmpdir(), 'dsh-store-')), 'agentdebug.sqlite')\n  const bridge = new PythonBridge({ python, timeoutMs: 20_000 })\n  try {\n    const result = await bridge.request('diagnose', {\n      session: readSessionLog(file),\n      store,\n      mode: 'heuristic',\n    })\n    assert.equal(result.summary.traceId, 'dsh_session-abc')\n    assert.equal(typeof result.summary.reportId, 'string')\n  } finally {\n    await bridge.close()\n  }\n})\n\ntest('system turns are hoisted out of the host request', () => {\n  const request = toHostRequest([\n    { role: 'system', content: 'You localize failures.' },\n    { role: 'user', content: 'Which step broke?' },\n    { role: 'assistant', content: [{ type: 'text', text: 'Step 3.' }] },\n  ])\n\n  assert.equal(request.system, 'You localize failures.')\n  assert.deepEqual(request.messages.map(message => message.role), ['user', 'assistant'])\n  assert.equal(request.messages[1].content[0].text, 'Step 3.')\n})\n\ntest('a streamed answer is assembled into one completion', async () => {\n  const seen = {}\n  const ctx = {\n    llm: {\n      async *stream(options) {\n        Object.assign(seen, options)\n        yield { type: 'block-start', index: 0, blockType: 'text' }\n        yield { type: 'text-delta', index: 0, text: 'Step 3 ' }\n        yield { type: 'text-delta', index: 0, text: 'broke it.' }\n        yield { type: 'reasoning-delta', index: 1, text: 'thinking out loud' }\n        yield { type: 'usage', usage: { inputTokens: 12, outputTokens: 5 } }\n        yield { type: 'finish', reason: { kind: 'stop' } }\n      },\n    },\n  }\n\n  const result = await completeWithHost(ctx, { provider: 'p', model: 'm' }, {\n    messages: [{ role: 'user', content: 'Which step?' }],\n    responseFormat: { type: 'json_object' },\n    maxTokens: 512,\n  })\n\n  assert.equal(result.text, 'Step 3 broke it.')\n  assert.deepEqual(result.usage, { promptTokens: 12, completionTokens: 5 })\n  assert.equal(seen.model, 'm')\n  assert.equal(seen.maxTokens, 512)\n  // Harness generation options cannot express JSON mode, so the constraint has\n  // to reach the model through the prompt.\n  assert.match(seen.system, /single valid JSON object/)\n})\n\ntest('the session route is used unless an explicit pair overrides it', () => {\n  const session = { id: 'session-1', requestHeader: () => ({ config: { provider: 'p', model: 'm' } }) }\n\n  assert.deepEqual(resolveRoute({}, session), { provider: 'p', model: 'm', sessionId: 'session-1' })\n  assert.deepEqual(\n    resolveRoute({ llmProvider: 'other', llmModel: 'big' }, session),\n    { provider: 'other', model: 'big', sessionId: 'session-1' },\n  )\n  assert.throws(\n    () => resolveRoute({}, { id: 'session-2', requestHeader: () => undefined }),\n    /no request has been logged/,\n  )\n})\n\ntest('deep mode drives AgentDebugX through the host model', async () => {\n  const bridge = new PythonBridge({ python, timeoutMs: 120_000, onStderr: () => {} })\n  const prompts = []\n  bridge.serve('llm.complete', (route, params) => {\n    prompts.push({ route, messages: params.messages })\n    return {\n      text: JSON.stringify({\n        step: 1,\n        agent: 'dsh-agent',\n        summary: 'The tool call was malformed.',\n        evidence: 'Fix the build.',\n        correction: 'Send valid arguments.',\n        confidence: 0.6,\n      }),\n      usage: { promptTokens: 11, completionTokens: 7 },\n    }\n  })\n  const lease = bridge.lend({ provider: 'stub', model: 'stub-model' })\n  try {\n    const result = await bridge.request('diagnose', {\n      session: {\n        id: 'session-deep',\n        header: { cwd: 'C:/workspace' },\n        events: [\n          { type: 'turn/start', seq: 0, time: 1, data: { turn: 1 } },\n          {\n            type: 'user/message',\n            seq: 1,\n            time: 2,\n            data: { role: 'user', content: [{ type: 'text', text: 'Fix the build.' }] },\n          },\n          { type: 'turn/end', seq: 2, time: 3, data: { turn: 1, reason: { kind: 'completed' } } },\n        ],\n      },\n      store: path.join(mkdtempSync(path.join(tmpdir(), 'dsh-store-')), 'agentdebug.sqlite'),\n      mode: 'deep',\n      llm: { token: lease.token, model: 'stub-model' },\n    })\n\n    assert.ok(prompts.length > 0, 'expected the bridge to call back into the host model')\n    assert.equal(prompts[0].route.model, 'stub-model')\n    assert.ok(\n      JSON.stringify(prompts[0].messages).includes('Fix the build.'),\n      'expected the trajectory to reach the host model',\n    )\n    assert.equal(result.summary.mode, 'deep')\n    assert.equal(result.summary.deepError, undefined)\n    assert.equal(typeof result.summary.reportId, 'string')\n  } finally {\n    lease.release()\n    await bridge.close()\n  }\n})\n\ntest('a forged route token cannot spend host tokens', async () => {\n  const bridge = new PythonBridge({ python, timeoutMs: 60_000, onStderr: () => {} })\n  let calls = 0\n  bridge.serve('llm.complete', () => {\n    calls += 1\n    return { text: '{}' }\n  })\n  try {\n    const result = await bridge.request('diagnose', {\n      session: {\n        id: 'session-forged',\n        header: {},\n        events: [\n          { type: 'turn/start', seq: 0, time: 1, data: { turn: 1 } },\n          {\n            type: 'user/message',\n            seq: 1,\n            time: 2,\n            data: { role: 'user', content: [{ type: 'text', text: 'Fix the build.' }] },\n          },\n          { type: 'turn/end', seq: 2, time: 3, data: { turn: 1, reason: { kind: 'completed' } } },\n        ],\n      },\n      store: path.join(mkdtempSync(path.join(tmpdir(), 'dsh-store-')), 'agentdebug.sqlite'),\n      mode: 'deep',\n      llm: { token: 'route-does-not-exist', model: 'stub' },\n    })\n\n    assert.equal(calls, 0, 'an unknown token must not reach the model')\n    // DeepDebug's tiers absorb failed calls and can still assemble a verdict.\n    // A verdict no model ever saw must not be labelled a deep diagnosis, and\n    // the transport failure must survive that internal error handling.\n    assert.equal(result.summary.mode, 'heuristic')\n    assert.match(result.summary.deepError, /no host model call succeeded/)\n    assert.match(result.summary.deepError, /expired or unknown route token/)\n  } finally {\n    await bridge.close()\n  }\n})\n\ntest('Python bridge reports the installed AgentDebugX surface', async () => {\n  const bridge = new PythonBridge({ python, timeoutMs: 20_000 })\n  try {\n    const capabilities = await bridge.request('capabilities')\n    assert.ok(capabilities.ingestFormats.includes('osworld'))\n    assert.ok(capabilities.diagnoseComponents.some(\n      component => component.id === 'detect.heuristic' && component.enabledByDefault,\n    ))\n    assert.ok(capabilities.diagnoseComponents.some(\n      component => component.id === 'detect.llm_judge' && component.requiresLlm,\n    ))\n  } finally {\n    await bridge.close()\n  }\n})\n\ntest('Python bridge returns contained protocol errors', async () => {\n  const bridge = new PythonBridge({\n    python,\n    timeoutMs: 10_000,\n  })\n  try {\n    await assert.rejects(\n      bridge.request('not-a-method'),\n      /ValueError: unknown bridge method/,\n    )\n  } finally {\n    await bridge.close()\n  }\n})\n"
